from pathlib import Path

path = Path('docs/CONTENT-CONVERSION-REVISION-PLAN.md')
text = path.read_text(encoding='utf-8')

def replace_once(old, new):
    global text
    count = text.count(old)
    if count != 1:
        raise ValueError(f'Expected one marker, found {count}: {old[:90]}')
    text = text.replace(old, new, 1)

replace_once('Статус: **правила утверждены; R1–R3 опубликованы, следующие итерации — по плану**.', 'Статус: **R1–R4 опубликованы; перед R5 предусмотрена корректирующая R4.1 по понятности гайда P01**.')
replace_once('## 4. Очередь: девять реализационных итераций + итоговая приёмка', '## 4. Очередь: R1–R9, обязательная корректировка R4.1 и итоговая приёмка R10')
replace_once('Замена четырёх фотографий бань — отдельный незакрытый запрос;', 'Четыре фотографии бань отдельно опубликованы в PR #21;')
original_r4 = '| **R4** | Три услуги: **штукатурка, стяжка, бурение**, плюс `/services/` | Единая логика оффера: для кого, что получает клиент, известный ценовой ориентир с единицами, что нужно для расчёта, реальные преимущества и простая заявка. Согласованность с гайдами, без неоговорённых «под ключ»/гарантий. | ☐ План |'
new_r4 = original_r4.replace('☐ План', '☑ Выполнено · PR #22; CI и Pages успешны, ручной мобильный просмотр/отправка WhatsApp не проверены')
r4a = '| **R4.1** | **Исправление P01**: информационный гайд о механизированной и ручной штукатурке; точечная проверка P02/S01/S04 на такую же перегрузку | Простой ответ и стоимость без кликов, необязательные детали технологии, вместо 8×2 списков — короткий чек-лист «что входит в цену»; ясное обращение и отсутствие пустого экрана «Надо уточнить». Менять соседние гайды лишь при доказанном перегрузе. | ☐ **Перед R5**, клиентская понятность прежней R1/R2 не подтверждена |'
replace_once(original_r4, new_r4 + '\n' + r4a)
replace_once('Выполнять **R1 → R10**;', 'Выполнять **R1 → R10**, обязательно поставив **R4.1 между R4 и R5**;')

addendum = '''### R4.1 — обязательное исправление сложности для покупателя

**Сигнал:** посетитель видит в гайде P01 «Что общее / где разница», пять этапов, затем «Одна / две сметы» и много одинаковых «Надо уточнить» для двух технологий. Это не расчёт цены, но выглядит как обязательная сложная анкета и не объясняет, зачем её заполнять. R1/R2 технически реализованы и протестированы, однако замечание по понятности остаётся открытым; R10 не должна быть первым местом его решения.

**Не путать страницы:** `/mehanizirovannaya-shtukaturka-omsk/` — услуга с оффером и ценой, улучшена в R4. `/guides/remont/mehanizirovannaya-ili-ruchnaya-shtukaturka/` — сравнительный гайд P01; здесь нужен отдельный UX-ремонт, не копирование лендинга.

1. На первом экране без кликов: понятная разница технологий, что предлагает компания, цена механизированной штукатурки **от 550 ₽/м²** со ссылкой на коммерческую страницу, и действие «Пришлите площадь и фото стен — обсудим расчёт».
2. Вместо обязательного выбора пяти этапов: 3–4 компактных карточки с практической пользой. Технологические подробности — только по желанию, в раскрывающемся блоке; термины не должны заслонять ответ.
3. Вместо обязательной матрицы 8 позиций × 2 подрядчика: короткий понятный чек-лист «что включено, какие материалы, подготовка, доставка, итоговый результат, возможные доплаты». Результат виден сразу. Подробное сравнение двух реальных смет показывать лишь желающим; если не помогает — убрать. Пустое состояние не выглядит как 0/8 и бесконечное «Надо уточнить». Не выдумывать окончательную стоимость или исходные ответы клиента.
4. Чёткий CTA в начале и после полезного ответа без заполнения таблиц. Объяснить, что площадь и фотографии нужны для индивидуального расчёта; безопасность и достоверные условия остаются.
5. Проверить аналогичные гайды P02, S01 и S04 глазами посетителя: есть ли ранний ответ, зачем нажимать и что получится. Исправить лишь подтверждённые сложности, не удаляя полезные сведения.
6. Критерий приёмки: обычный посетитель за **5–10 секунд без взаимодействия** видит ответ, ориентир цены и следующий шаг; без анкеты понимает, что спросить перед заказом. Проверить mobile/desktop, доступность, все оставшиеся состояния, ссылки, JS и HTML без JS, отдельный PR, CI и Pages. Не объявлять этап закрытым только по результату сборки; ручной просмотр отмечать отдельно.

**Статус:** ☐ В очереди перед R5; изменения страницы и интерактивов ещё не внесены.

'''
replace_once('## 5. Что именно вынесли из двух ревью P01', addendum + '## 5. Что именно вынесли из двух ревью P01')
replace_once('После R10 не должно остаться URL без ревизии, тупиковых CTA и расхождений между runtime и prerender.', 'После R10 не должно остаться URL без ревизии, тупиковых CTA и расхождений между runtime и prerender. Отдельно проверяем простоту начального экрана и отсутствие обязательных длинных таблиц без понятной ранней пользы; R4.1 должна быть закрыта до R10.')
path.write_text(text, encoding='utf-8')
print('R4.1 added to master plan, R4 marked published; user-acceptance criteria recorded.')
